def tgt_mask(tgt_seq):
    batch_size, tgt_seq_len = tgt_seq.size()
    attn_shape = [batch_size, tgt_seq_len, tgt_seq_len]
    # 生成上三角矩阵
    tgt_mask_np = np.triu(np.ones(attn_shape), k=1)
    return torch.from_numpy(tgt_mask_np).byte().to(device)

